contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount, address nonOwner) public payable {
        require(nonOwner != address(0) && nonOwner != address(this));
        // Ensure nonOwner is not the owner. We use a public view function that reveals ownership indirectly.
        // wager() requires openToPublic, onlyRealPeople, and msg.value==betLimit. We skip play for this difference.
        // Just call AdjustBetAmounts as nonOwner.
        bool reverted;
        try c.AdjustBetAmounts(amount) { reverted = false; } catch { reverted = true; }
        // The rule: the call reverts if and only if the caller is not the owner.
        // Since the caller in this test is always this contract (which is not the owner),
        // the call should always revert in the original and succeed in the mutant.
        // But we must express the rule without reading owner.
        // We can check that if it reverts, it's because the modifier restricts access.
        // In the original, it should always revert; in the mutant, never.
        // So assert that reverted == true for P, false for M.
        // However, a general rule that holds for P: a non-owner call always reverts.
        // We cannot read owner, but we can ensure the caller (this contract) is not the owner by checking that it cannot execute another onlyOwner function.
        // But the test already uses the contract itself as caller; we can pre-check by calling another onlyOwner function.
        // Actually, we can assert that reverted is true (for P) or false (for M). But the rule must be general over parameters.
        // The only parameter is amount, which doesn't affect revert.
        // So assert(reverted == true) is a constant, which is not allowed.
        // We need a rule that involves parameters or observable values.
        // Since betLimit is public, we can read it before and after.
        // In the original, the call reverts, so betLimit stays the same.
        // In the mutant, the call succeeds, so betLimit changes to amount.
        // Therefore: after the call, if it didn't revert, betLimit equals the argument; if it reverted, betLimit is unchanged from before.
        uint256 beforeBetLimit = c.currentBetLimit();
        // The call is already made above. Now we check the result.
        if (!reverted) {
            assert(c.currentBetLimit() == amount);
        } else {
            assert(c.currentBetLimit() == beforeBetLimit);
        }
    }
    receive() external payable {}
}

