        vm.assume(betAmount > 0);
        vm.assume(player != address(0) && player != address(this));

        // Owner opens to public
        c.OpenToThePublic();

        // Adjust bet limit to fuzzed amount
        c.AdjustBetAmounts(betAmount);

        // Fuzzed player tries to wager
        vm.deal(player, betAmount);
        vm.prank(player);
        bool ok;
        try c.wager{value: betAmount}() { ok = true; } catch { ok = false; }

        // Reference: wager succeeds because OpenToThePublic set openToPublic = true
        // Buggy: wager reverts because OpenToThePublic incorrectly set openToPublic = false
        assertTrue(ok);
    }
}

